"handle": "@george__mack",
"cat": "Kariyer",
"type": "thread",
"summary": "George Mack'e göre dünyaya bakışını değiştiren fikir “yüksek inisiyatif” (high agency): kurallara değil sonuca odaklanan, engel karşısında yol bulan insan olmak. Thread bunu 12 örnekle anlatıyor.",
"title": "",
"text": "What idea changed how you view the world?<br><br>Here&#x27;s mine: High Agency.<br><br>The 12 best examples: <a href=\"https://t.co/qPjjh4KytE\" target=\"_blank\" rel=\"noopener nofollow\">pic.twitter.com/qPjjh4KytE</a>",
"lang": "en",
