"text": "The most useful razors and rules I&#x27;ve found.<br><br>Rules of thumb that simplify decisions: <a href=\"https://t.co/3nfxFujviP\" target=\"_blank\" rel=\"noopener nofollow\">pic.twitter.com/3nfxFujviP</a>",
