"url": "https://x.com/Kpaxs/status/2087173064601608641",
"author": "Kpaxs",
"handle": "@Kpaxs",
"cat": "Çeşitli",
"type": "tweet",
"summary": "İnisiyatifi düşük olan, ilk adımdan önce tam cevabı bekler; yüksek olan adımı atar ve ikinci adım için bilgi toplar. Yapay zekâ ikinci tipi katlayarak hızlandırıyor.",
"title": "",
"text": "Low agency wants the complete answer before the first step.<br><br>High agency takes the first step to generate information about the second step<br><br>AI is insanely good for the second guy. You can now iterate at a speed that would&#x27;ve been science fiction in 2019. But it is nearly useless…",
