"text": "If you can create a product that&#x27;s Instagrammable and Pinterest-board-worthy, you will do numbers.<br><br>Aesthetics run the world, and nobody, or should I say no woman, buys ugly shit.<br><br>And sad floating fruit in a water bottle is ugly, so if you create one with frosted glass that… <a href=\"https://t.co/EHMRHuX5Ca\" target=\"_blank\" rel=\"noopener nofollow\">https://t.co/EHMRHuX5Ca</a> <a href=\"https://t.co/mqzdI0VaWb\" target=\"_blank\" rel=\"noopener nofollow\">pic.twitter.com/mqzdI0VaWb</a>",
