"author": "John Carmack",
"handle": "@ID_AA_Carmack",
"cat": "Yazılım",
"type": "tweet",
"summary": "Carmack, Jonathan Blow'un “bugün neden yeni bir işletim sistemi yazmayı düşünemiyoruz” sorusunu, kendisine akıllı gözlükler için özel bir işletim sistemi öneren bir e-posta üzerinden yorumluyor.",
"title": "",
"text": "I had been meaning to comment on <a href=\"https://x.com/Jonathan_Blow?ref_src=twsrc%5Etfw\" target=\"_blank\" rel=\"noopener nofollow\">@Jonathan_Blow</a>’s “Why can’t we even conceive of writing a new OS today” post. Coincidentally, I just got an email that opened with:<br><br>———————————————<br>Hey John,<br><br>2 years ago I pitched you LIBBA - a dedicated OS for smart glasses.<br><br>You were…",
