"text": "This is a story about how I lost $10,000,000 by doing something stupid.<br><br>Ten. Million. Dollars.<br><br>Literally up in smoke. Money bonfire.<br><br>That’s enough to retire with $250,000+ in annual income.<br><br>Here’s what happened…",
