"summary": "Alan Cooper, birlikte çalıştığı “10x” programcıların parlak olduğunu ama ürettiklerinin çoğu zaman gerçek bir ürüne dönüşmediğini anlatıyor; bireysel dehadan çok ekip ve işbirliğinin önemini vurguluyor.",
"title": "",
"text": "I’ve worked with more than one “10x” programmer. Their brilliance is astonishing, but their output is rarely practically realized. 1",
"lang": "en",
"date": "14 Temmuz 2019",
"hm": 266,
"hd": 273
