"summary": "Vlad Mihalcea, teknik bir kitabı kendi yayımlayarak 100 bin dolardan fazla nasıl kazandığını anlatıyor: önce blogla yazmayı pratik edip kitle oluşturmak, sonra o kitleye ürünü sunmak.",
