"handle": "@amasad",
"cat": "Açık Kaynak",
"type": "tweet",
"summary": "Amjad Masad, yalnızca ağırlıkları yayımlanan modellerin gerçek anlamda açık kaynak sayılamayacağını, modeli yeniden üretebilmek için veri ve eğitim sürecinin de açık olması gerektiğini savunuyor.",
"title": "",
"text": "The open-source AI revolution hasn’t happened yet!<br><br>Yes we have impressive open-weights models, and thank you to those publishing weights, but if you can’t reproduce the model then it’s not truly open-source.<br><br>Imagine if Linux published only a binary without the codebase. Or…",
