"handle": "@tef_ebooks",
"cat": "Öğrenme",
"type": "thread",
"summary": "Patent memuru Kazushige Goto'nun iki saatlik işe gidiş yolunda kendi kendine çalışarak dünyanın en iyi assembly optimizasyoncularından biri hâline gelişini anlatıyor; düzenli küçük çabanın gücünü gösteriyor.",
"title": "",
"text": "becoming one of those &quot;old programmers&quot; as i relay another piece of folklore, this time about Kazushige Goto, a japanese patent clerk who ended up becoming one of the world&#x27;s best assembly optimisers<br><br>as it was something to do on his two hour commute to work",
