"author": "Andrew Wilkinson",
"handle": "@awilkinson",
"cat": "Öğrenme",
"type": "thread",
"summary": "Andrew Wilkinson, taklitçi arzu (mimetic desire) kavramını anlatan bir kitabın, insanların neden kendilerini mutsuz eden hedeflerin peşinden koştuğunu açıkladığını söylüyor ve ana fikirleri özetliyor.",
"title": "",
"text": "I read a book that blew my mind a little and I can’t stop telling people about it.<br><br>It explains why so many people dedicate their lives to achieving things that make them miserable.<br><br>This might sound crazy, but an unseen force is pushing you towards empty and unfulfilling goals…",
