"author": "Brad Neuberg",
"handle": "@bradneuberg",
"cat": "Girişim",
"type": "tweet",
"summary": "YC modelinin, temel teknolojinin başkaları tarafından finanse edildiği ve az sermayeyle girişim kurulabildiği bir döneme dayandığını; yeni dönemin sermaye yoğun teknolojilerinin bu modeli zorladığını savunuyor.",
"title": "",
"text": "Y Combinator is predicated on startups that require low capitalization since most of the technology they depend on is already mostly developed. This was true pre-2015 where startups depended on commodity open source software, the smartphone capitalized by Apple and others, cloud…",
"lang": "en",
