"summary": "Büyük bir şey yaratmanın yolu mutlaka bir “umutsuzluk bataklığından” geçer; Bill Gross'a göre dışarıdan bakanlar bu süreçteki çılgın inancı ve ısrarı neredeyse hiç görmez.",
"title": "",
"text": "The emotional journey of creating anything great requires crossing the dark swamp of despair..<br><br>Outsiders almost never see the crazy belief and persistence required to cross that chasm.. <a href=\"https://t.co/iyZBKw5zE8\" target=\"_blank\" rel=\"noopener nofollow\">pic.twitter.com/iyZBKw5zE8</a>",
"lang": "en",
"date": "26 Mayıs 2018",
