"summary": "Çalıştığı bir şirkette her şeyin yıllık ikramiyeye bağlandığını ve bunun çalışanları birbirine düşürdüğünü anlatıyor; yanlış teşvik sistemlerinin kültürü nasıl çürüttüğünü gösteriyor.",
