"summary": "Bir e-posta listesinden çıkışın neden “birkaç gün” sürebildiğini, büyük bir kurumda yaşadığı absürt bir entegrasyon hikâyesiyle açıklıyor; kurumsal sistemlerin gizli karmaşıklığını gösteriyor.",
