"author": "Robert Colvile",
"handle": "@rcolvile",
"cat": "Yazılım",
"type": "thread",
"summary": "Modern devletin en önemli işlevinin ve en büyük kısıtının aslında veritabanı yönetimi olduğunu, aşı pasaportu tartışması üzerinden ilgi çekici biçimde anlatıyor.",
"title": "",
"text": "The vaccine passports debate is a perfect illustration of my new working theory: that the most important part of modern government, and its most important limitation, is database management. Please stick with me on this - it&#x27;s much more interesting than it sounds. (1/?)",
