"url": "https://x.com/SahilBloom/status/1571137341997318147",
"author": "Sahil Bloom",
"handle": "@SahilBloom",
"cat": "Çeşitli",
"type": "thread",
"summary": "Sahil Bloom, ebeveynleriyle geçirebileceği kalan zamanı hesapladığı bir konuşmanın onu ülkenin öbür ucuna taşınmaya ikna ettiğini anlatıyor; sevdiklerimizle geçen zamanın sınırlı olduğunu hatırlatıyor.",
"title": "",
"text": "Last year, I had a conversation that changed my life.<br><br>It caused me to upend everything and move across the country.<br><br>The lesson from it may change yours:",
"lang": "en",
"date": "17 Eylül 2022",
"hm": 323,
"hd": 345
