"cat": "Yapay Zekâ",
"type": "makale",
"summary": "Yapay zekâ ajanlarının rahatça kullanabileceği komut satırı araçları tasarlamak için on ilke sunuyor; ajanların CLI'ları nerede ve nasıl bozduğuna dair gözlemlere dayanıyor.",
"title": "10 Principles for Agent-Native CLIs",
"text": "<a href=\"https://t.co/E6YY79onuU\" target=\"_blank\" rel=\"noopener nofollow\">https://t.co/E6YY79onuU</a>",
"lang": "zxx",
