"handle": "@anuatluru",
"cat": "Öğrenme",
"type": "tweet",
"summary": "En hızlı öğrenen, bilgiyi hemen kullanmak zorunda olan kişidir. Hızlı öğrenmek istiyorsan, o bilgiyi gerektiren bir işe bir an önce söz ver.",
