"type": "tweet",
"summary": "Binlerce çekme isteğini (pull request) birleştirmiş birinin gözlemleri: neredeyse kimse iyi başlık yazmıyor, çoğu \"Fixes #112\" sözdizimini bilmiyor, yaklaşık %30'u testleri çalıştırmıyor, %40'ı belge ya da test eklemiyor.",
"title": "",
"text": "Some observations from having merged thousands of pull requests in the past few years:<br>- Almost no one writes a good pull request title<br>- More than half don&#x27;t know about the `Fixes #112` syntax<br>- ~30% don&#x27;t run tests locally before submitting a PR<br>- ~40% don&#x27;t include docs/tests",
"lang": "en",
