"summary": "Uygulamalarına yüksek fiyat koymak açgözlülük değil, kendini korumaktır. Ücretsiz ve ucuz ürünler çok daha fazla destek yükü getirir; daha az satıp daha kaliteli müşteri kazanmak çoğu zaman daha iyidir.",
"title": "",
"text": "I have a high price tier on my macOS apps, not because I&#x27;m greedy or earn a lot from them, but rather because life is too short to deal with idiots. For example, free &amp; cheap apps require much more support. I&#x27;d rather sell fewer copies in favor of getting higher quality customers",
